STARTER_SOURCE = "from __future__ import annotations\n\nimport asyncio\nimport threading\nfrom collections.abc import AsyncIterator, Awaitable, Callable\nfrom dataclasses import dataclass\n\n\n@dataclass(frozen=True)\nclass FlightInfo:\n    active: int\n    joined: int\n    total: int\n\n\nclass _CallState:\n    def __init__(self, owner: asyncio.Task | None) -> None:\n        self.owner = owner\n        self.lock = threading.Lock()\n        self.done = False\n        self.result: object = None\n        self.error: BaseException | None = None\n        self.waiters: list[tuple[asyncio.AbstractEventLoop, asyncio.Future]] = []\n\n    @staticmethod\n    def _resolve(\n        waiter: asyncio.Future,\n        result: object,\n        error: BaseException | None,\n    ) -> None:\n        if waiter.done():\n            return\n        if error is None:\n            waiter.set_result(result)\n        else:\n            waiter.set_exception(error)\n\n    def _notify(\n        self,\n        waiters: list[tuple[asyncio.AbstractEventLoop, asyncio.Future]],\n        result: object,\n        error: BaseException | None,\n    ) -> None:\n        for loop, waiter in waiters:\n            try:\n                loop.call_soon_threadsafe(self._resolve, waiter, result, error)\n            except RuntimeError:\n                pass\n\n    def complete(self, result: object, error: BaseException | None) -> None:\n        with self.lock:\n            self.result = result\n            self.error = error\n            self.done = True\n            waiters = self.waiters\n            self.waiters = []\n        self._notify(waiters, result, error)\n\n    def remove_waiter(self, waiter: asyncio.Future) -> None:\n        with self.lock:\n            self.waiters = [entry for entry in self.waiters if entry[1] is not waiter]\n\n    async def wait(self) -> object:\n        loop = asyncio.get_running_loop()\n        with self.lock:\n            if self.done:\n                waiter = None\n                result = self.result\n                error = self.error\n            else:\n                waiter = loop.create_future()\n                self.waiters.append((loop, waiter))\n                result = None\n                error = None\n\n        if waiter is not None:\n            try:\n                return await waiter\n            finally:\n                self.remove_waiter(waiter)\n        if error is not None:\n            raise error\n        return result\n\n\nclass _StreamState:\n    def __init__(self, owner: asyncio.Task | None) -> None:\n        self.owner = owner\n        self.lock = threading.Lock()\n        self.items: list[object] = []\n        self.done = False\n        self.error: BaseException | None = None\n        self.waiters: list[tuple[asyncio.AbstractEventLoop, asyncio.Future]] = []\n        self.producer: asyncio.Task | None = None\n\n    @staticmethod\n    def _resolve(waiter: asyncio.Future) -> None:\n        if not waiter.done():\n            waiter.set_result(None)\n\n    def _notify(self, waiters: list[tuple[asyncio.AbstractEventLoop, asyncio.Future]]) -> None:\n        for loop, waiter in waiters:\n            try:\n                loop.call_soon_threadsafe(self._resolve, waiter)\n            except RuntimeError:\n                pass\n\n    def append(self, item: object) -> None:\n        with self.lock:\n            self.items.append(item)\n            waiters = self.waiters\n            self.waiters = []\n        self._notify(waiters)\n\n    def complete(self, error: BaseException | None) -> None:\n        with self.lock:\n            self.error = error\n            self.done = True\n            waiters = self.waiters\n            self.waiters = []\n        self._notify(waiters)\n\n    def remove_waiter(self, waiter: asyncio.Future) -> None:\n        with self.lock:\n            self.waiters = [entry for entry in self.waiters if entry[1] is not waiter]\n\n\nclass AsyncSingleFlight:\n    def __init__(self) -> None:\n        self._lock = threading.Lock()\n        self._states: dict[tuple[str, object], object] = {}\n        self._stats = [0, 0, 0]\n\n    def _acquire(\n        self,\n        lane: str,\n        key: object,\n        factory: Callable[[], object],\n    ) -> tuple[bool, object]:\n        token = (lane, key)\n        hash(token)\n        owner = asyncio.current_task()\n        with self._lock:\n            if token in self._states:\n                self._stats[2] += 1\n                if self._states[token].owner is owner:\n                    raise RuntimeError(\"reentrant single-flight dependency\")\n                self._stats[1] += 1\n                return False, self._states[token]\n            self._stats[2] += 1\n            state = factory(owner)\n            self._states[token] = state\n            self._stats[0] += 1\n            return True, state\n\n    def _finish(self, lane: str, key: object, state: object) -> None:\n        token = (lane, key)\n        with self._lock:\n            if self._states.get(token) is state:\n                del self._states[token]\n                self._stats[0] -= 1\n\n    async def run(\n        self,\n        key: object,\n        factory: Callable[[], Awaitable[object]],\n    ) -> object:\n        leader, state = self._acquire(\"run\", key, _CallState)\n        if not leader:\n            return await state.wait()\n        try:\n            result = await factory()\n        except BaseException as exc:\n            state.complete(None, exc)\n            raise\n        else:\n            state.complete(result, None)\n            return result\n        finally:\n            self._finish(\"run\", key, state)\n\n    async def _produce_stream(\n        self,\n        key: object,\n        state: _StreamState,\n        factory: Callable[[], AsyncIterator[object]],\n    ) -> None:\n        error = None\n        try:\n            async for item in factory():\n                state.append(item)\n        except BaseException as exc:\n            error = exc\n        finally:\n            state.complete(error)\n            self._finish(\"stream\", key, state)\n\n    async def stream(\n        self,\n        key: object,\n        factory: Callable[[], AsyncIterator[object]],\n    ) -> AsyncIterator[object]:\n        leader, state = self._acquire(\"stream\", key, _StreamState)\n        if leader:\n            state.producer = asyncio.create_task(self._produce_stream(key, state, factory))\n            state.owner = state.producer\n\n        index = len(state.items)\n        while True:\n            waiter = None\n            with state.lock:\n                if state.done and state.error is not None:\n                    done = True\n                    error = state.error\n                elif index < len(state.items):\n                    item = state.items[index]\n                    index += 1\n                    done = False\n                    error = None\n                elif not state.done:\n                    loop = asyncio.get_running_loop()\n                    waiter = loop.create_future()\n                    state.waiters.append((loop, waiter))\n                    done = False\n                    error = None\n                else:\n                    done = True\n                    error = None\n            if waiter is not None:\n                try:\n                    await waiter\n                except asyncio.CancelledError:\n                    state.remove_waiter(waiter)\n                    raise\n                continue\n            if done:\n                if error is not None:\n                    raise error\n                return\n            yield item\n\n    def info(self) -> FlightInfo:\n        with self._lock:\n            return FlightInfo(*self._stats)\n\n    def clear(self) -> None:\n        with self._lock:\n            if self._stats[0]:\n                raise RuntimeError(\"cannot clear while flights are active\")\n            self._stats = [0, 0, 0]\n\n\n__all__ = [\"AsyncSingleFlight\", \"FlightInfo\"]\n"
